import React, { Component } from 'react';
import moment from 'moment';
import { requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import {
    CButton,
    CCol,
    CContainer,
    CInput,
    CInputGroup,
    CInputGroupPrepend,
    CInputGroupText,
    CModal,
    CModalBody,
    CModalFooter,
    CModalHeader,
    CModalTitle,
    CRow,
} from '@coreui/react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import MaterialReactTable from 'material-react-table';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "YoutubeVideos.js";

const initialState = {
    isLoaded: false,
    loadingModalVisible: false,
    loadingModalState: 0,
    failureModalVisible: false,
    videoListData: [],
    page: 1,
    size: 50,
    totalPages: 0,
    totalElements: 0,
    search: '',
    apiResponseModalVisible: false,
    apiResponseModalContent: '',
    apiResponseModalParseError: false,
    apiResponseModalTitle: '',
};

const videoTableColumnData = [
    {
        accessorKey: 'id',
        header: 'ID',
        size: 60,
    },
    {
        accessorKey: 'thumbnailBase64',
        header: 'Thumbnail',
        size: 120,
        enableSorting: false,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue
                ? <img src={renderedCellValue} alt="video" style={{ width: '100px', height: '56px', borderRadius: '4px' }} />
                : '—'
        ),
    },
    {
        accessorKey: 'title',
        header: 'Title',
        size: 300,
        Cell: ({ renderedCellValue }) => (
            <span title={renderedCellValue} style={{ display: 'block', maxWidth: '300px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {renderedCellValue || '—'}
            </span>
        ),
    },
    {
        accessorKey: 'channelId',
        header: 'Channel',
        size: 90,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue
                ? <a href={'#/youtube/channel/' + renderedCellValue} target="_blank" rel="noopener noreferrer">{renderedCellValue}</a>
                : '—'
        ),
    },
    {
        accessorKey: 'youtubeVideoId',
        header: 'Video ID',
        size: 120,
    },
    {
        accessorKey: 'link',
        header: 'Link',
        Cell: ({ renderedCellValue }) => (
            renderedCellValue
                ? <a href={renderedCellValue} target="_blank" rel="noopener noreferrer">Watch</a>
                : '—'
        ),
    },
    {
        accessorKey: 'downloaded',
        header: 'Download Info',
        size: 220,
        enableSorting: false,
        Cell: ({ row }) => {
            const v = row.original;
            return (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
                    <span><strong>downloaded:</strong> {v.downloaded ? '✅ true' : '❌ false'}</span>
                    <span><strong>shouldDownload:</strong> {v.shouldDownload ? '✅ true' : '❌ false'}</span>
                    <span style={{ wordBreak: 'break-word' }}><strong>downloadedFileName:</strong> {v.downloadedFileName || '—'}</span>
                </div>
            );
        },
    },
    {
        accessorKey: 'uploadDate',
        header: 'Upload Date',
        size: 140,
    },
    {
        accessorKey: 'createdOn',
        header: 'Added On',
        size: 180,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue ? moment(renderedCellValue).format('YYYY/MM/DD HH:mm:ss ddd') : '—'
        ),
    },
];

class YoutubeVideos extends Component {

    constructor(props) {
        super(props);
        this.state = JSON.parse(JSON.stringify(initialState));
    }

    resetStateToDefault() {
        this.setState(JSON.parse(JSON.stringify(initialState)));
    }

    reloadData() {
        this.resetStateToDefault();
        setTimeout(() => this.fetchVideoList(), 0);
    }

    openApiResponseModal = (video) => {
        const raw = video.apiResponseJson;
        let content;
        let parseError = false;
        if (raw === null || raw === undefined || raw === '') {
            content = 'No API response data available.';
        } else {
            try {
                content = JSON.stringify(JSON.parse(raw), null, 2);
            } catch (e) {
                // Not valid JSON — show the raw string instead of failing.
                Logger(FILE_NAME, "openApiResponseModal", "", "parseError", e);
                content = raw;
                parseError = true;
            }
        }
        this.setState({
            apiResponseModalVisible: true,
            apiResponseModalContent: content,
            apiResponseModalParseError: parseError,
            apiResponseModalTitle: video.title || ('Video #' + video.id),
        });
    }

    closeApiResponseModal = () => {
        this.setState({
            apiResponseModalVisible: false,
            apiResponseModalContent: '',
            apiResponseModalParseError: false,
            apiResponseModalTitle: '',
        });
    }

    componentDidMount() {
        document.title = "YouTube Videos";
        this.fetchVideoList();
    }

    fetchVideoList() {
        const { page, size, search } = this.state;
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/youtube/videos';
        const userData = getUserDataFromLocalStorage();

        const reqData = { page, size, search: search || null };
        Logger(FILE_NAME, "fetchVideoList", "", "reqData", reqData);

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ failureModalVisible: true });
                setTimeout(() => {
                    logoutProcedureForLocalStorage();
                    reloadPage();
                }, 500);
            } else {
                this.setState({ failureModalVisible: true });
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "fetchVideoList", "FETCH_1", "result", result);
                const pageData = result.data;
                this.setState({
                    isLoaded: true,
                    videoListData: pageData.content || [],
                    totalPages: pageData.totalPages || 0,
                    totalElements: pageData.totalElements || 0,
                });
            },
            (error) => {
                Logger(FILE_NAME, "fetchVideoList", "FETCH_1", "error", error);
                this.setState({ failureModalVisible: true, isLoaded: true });
            }
        );
    }

    handleSearchChange = (event) => {
        this.setState({ search: event.target.value });
    }

    handleSearchSubmit = (event) => {
        event.preventDefault();
        this.setState({ page: 1 }, () => this.fetchVideoList());
    }

    handlePrevPage = () => {
        if (this.state.page > 1) {
            this.setState({ page: this.state.page - 1 }, () => this.fetchVideoList());
        }
    }

    handleNextPage = () => {
        if (this.state.page < this.state.totalPages) {
            this.setState({ page: this.state.page + 1 }, () => this.fetchVideoList());
        }
    }

    render() {
        Logger(FILE_NAME, "render", "", "this.state", this.state);

        return (
            this.state.isLoaded ?
            <div>
                <h1>YouTube Videos &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
                    <CButton color="secondary" className="px-4" onClick={() => this.props.history.push('/youtube')}>← Back</CButton>
                    &nbsp;
                    <CButton color="success" className="px-4" onClick={() => this.reloadData()}>Reload Data</CButton>
                </h1>
                <br />

                {/* Search bar */}
                <CContainer className="mb-3">
                    <CRow className="justify-content-center">
                        <CCol md="6">
                            <form onSubmit={this.handleSearchSubmit}>
                                <CInputGroup>
                                    <CInputGroupPrepend>
                                        <CInputGroupText>🔍</CInputGroupText>
                                    </CInputGroupPrepend>
                                    <CInput
                                        placeholder="Search videos (title, description, link, video ID)..."
                                        type="text"
                                        value={this.state.search}
                                        onChange={this.handleSearchChange}
                                    />
                                    <CButton color="primary" type="submit" className="ml-2">Search</CButton>
                                </CInputGroup>
                            </form>
                        </CCol>
                    </CRow>
                </CContainer>

                {/* Videos table */}
                <MaterialReactTable
                    initialState={{ density: 'compact' }}
                    columns={[
                        ...videoTableColumnData,
                        {
                            accessorKey: 'actions',
                            header: 'Actions',
                            size: 130,
                            enableSorting: false,
                            Cell: ({ row }) => (
                                <CButton
                                    color="dark"
                                    size="sm"
                                    onClick={() => this.openApiResponseModal(row.original)}
                                >
                                    API Response
                                </CButton>
                            ),
                        },
                    ]}
                    data={this.state.videoListData}
                    enablePagination={false}
                    enableEditing={false}
                />

                {/* Pagination controls */}
                <CContainer className="mt-3">
                    <CRow className="justify-content-center align-items-center">
                        <CCol md="6" className="text-center">
                            <CButton
                                color="secondary"
                                disabled={this.state.page <= 1}
                                onClick={this.handlePrevPage}
                            >
                                ← Prev
                            </CButton>
                            &nbsp;&nbsp;
                            <span>
                                Page <strong>{this.state.page}</strong> of <strong>{this.state.totalPages}</strong>
                                &nbsp;({this.state.totalElements} total videos)
                            </span>
                            &nbsp;&nbsp;
                            <CButton
                                color="secondary"
                                disabled={this.state.page >= this.state.totalPages}
                                onClick={this.handleNextPage}
                            >
                                Next →
                            </CButton>
                        </CCol>
                    </CRow>
                </CContainer>

                {/* API Response modal */}
                <CModal
                    show={this.state.apiResponseModalVisible}
                    onClose={this.closeApiResponseModal}
                    size="lg"
                >
                    <CModalHeader closeButton>
                        <CModalTitle>API Response — {this.state.apiResponseModalTitle}</CModalTitle>
                    </CModalHeader>
                    <CModalBody>
                        {this.state.apiResponseModalParseError && (
                            <div style={{ color: '#e55353', marginBottom: '8px', fontSize: '0.9em' }}>
                                ⚠ Could not parse as JSON — showing raw value.
                            </div>
                        )}
                        <pre
                            style={{
                                maxHeight: '60vh',
                                overflow: 'auto',
                                background: '#f5f5f5',
                                padding: '12px',
                                borderRadius: '4px',
                                whiteSpace: 'pre-wrap',
                                wordBreak: 'break-word',
                                margin: 0,
                            }}
                        >
                            {this.state.apiResponseModalContent}
                        </pre>
                    </CModalBody>
                    <CModalFooter>
                        <CButton color="secondary" onClick={this.closeApiResponseModal}>Close</CButton>
                    </CModalFooter>
                </CModal>

                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
            : <Loading />
        );
    }
}

export default YoutubeVideos;
